preConditionHook:
// THE ASCENDING TRIANGLE: successively higher confirmed swing lows pressing
// into a FLAT resistance level -- a run of `legs` rising swing lows while the
// two most recent swing highs sit within levelTolAtr ATRs of each other
// (G04-16). Mirrored, the descending triangle: a run of `legs` falling swing
// highs into flat support.
//
// CARRIED AS ONE FILE although its two halves are separately meaningful --
// HigherSwingLowRun with its `legs` input is the rising-lows run, and
// LevelTouchCount is the flat-level read -- because LevelTouchCount's
// RESISTANCE reading sits on its SHORT side and a LONG placement cannot borrow
// it. That is the same side-assignment obstruction LowTouchesRecentRangeLow
// carries, and an AND across two panes cannot fix it: both halves of the
// ascending triangle belong to the long side. Both halves are inlined here, as
// the corpus does for Brooks's named setups.
//
// THE FLAT PAIR IS A NEW TEST. No catalog rule asks whether two PIVOTS are
// level with each other: LevelTouchCount counts BARS touching one pivot, Ledge
// counts bars sharing one extreme, and EqualHighsBreakout tests a run of
// adjacent BARS. Pivot against pivot is what a triangle's flat side is.
//
// NOT ExpandingTrianglePattern, the catalog's only triangle, which needs BOTH
// series DIVERGING over five pivots; this needs one series rising into the
// other held flat.
//
// THE RUN IS TESTED AS THE SCAN GOES, HigherSwingLowRun's construction: one
// comparison per newly found pivot against the previously found (NEWER) one,
// so no array and no numbered slots are needed for the run and `legs` is
// bounded only by pivotLookback. The occurrence 1 and 2 PRICES are captured
// separately for the flat-pair test on the other series. loPrev / hiPrev are
// only ever read once the count has reached 2, which is exactly when they were
// written earlier on the same bar.
//
// legs IS GUARDED AT 2 OR MORE: one pivot is not a run, and the flat pair needs
// two pivots of the opposite series, which the same `legs` cap supplies.
// Grimes's value is 3, the default here, as it is for HigherSwingLowRun's
// `legs`.
//
// THE TOLERANCE IS AN ATR FRACTION, never ticks (merge decision 7); 0.25 is the
// top of the decision's 0.1-to-0.25 band, right for a level two pivots must
// BOTH sit on. MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator:
// AtrProfitTarget's block verbatim, including the TWO separate accumulator
// statements, since EasyLanguage evaluates Summation[1] + Price - Price[Length]
// left to right, and the re-seed when the length changes.
//
// MEASURED (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min): the pivot
// bar is AT OR BEYOND the swingStrength OLDER bars and STRICTLY BEYOND the
// swingStrength NEWER bars -- bars-ago indexing makes the SMALLER kk the newer
// bar, so the strict half is the kk < jj loop; the confirmation lag is exactly
// swingStrength bars, so jj starts there; candidate offsets run 0..Length-1
// inclusive so jj stops at pivotLookback - 1, while the neighbourhood test
// reaches swingStrength bars PAST the window -- deepest bar touched
// pivotLookback - 1 + swingStrength; the comparisons carry the 2.22e-12
// relational tolerance; the low side's tie sense is the mirror of the measured
// high-side rule. Occurrence 3+ is UNMEASURED, which is why the scan is
// hand-rolled. No WFSafe_SwingLow exists, so plain EL governs. Written WITHOUT
// break, matching the twin statement for statement.
//
// THE SENTINEL IS GUARDED BY THE COUNTS, never by a price test: -1.00 and 0.00
// are legitimate prices in a back-adjusted series. AbsValue is ACCEPTED and
// std::fabs is its counterpart; <cmath> is already included by the emitter.
//
// Every scratch value that must survive the bar is a localVariables entry
// rather than a hook-scope declaration, so the hooks survive a double
// placement; the loop counters and per-candidate flags are block-scoped.
//
// Deepest bar touched:
// max(pivotLookback - 1 + swingStrength, atrLength + 1).
if (atrLenState != (int)atrLength) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLength; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLength;
} else {
    outIdx = (int)atrLength;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLength;
pivS = (int)swingStrength;
pivW = (int)pivotLookback;
nLo = 0;
nHi = 0;
loOk = true;
hiOk = true;
loPrev = 0.0;
hiPrev = 0.0;
loPx1 = 0.0;
loPx2 = 0.0;
hiPx1 = 0.0;
hiPx2 = 0.0;
for (int jj = pivS; jj <= pivW - 1; ++jj) {
    bool okLo = true;
    bool okHi = true;
    for (int kk = jj - pivS; kk < jj; ++kk) {
        if (el_ge(low[jj], low[kk])) okLo = false;
        if (el_le(high[jj], high[kk])) okHi = false;
    }
    for (int kk = jj + 1; kk <= jj + pivS; ++kk) {
        if (el_gt(low[jj], low[kk])) okLo = false;
        if (el_lt(high[jj], high[kk])) okHi = false;
    }
    if (okLo && el_lt((double)nLo, legs)) {
        nLo = nLo + 1;
        if (nLo >= 2 && el_le(loPrev, low[jj])) loOk = false;
        loPrev = low[jj];
        if (nLo == 1) loPx1 = low[jj];
        if (nLo == 2) loPx2 = low[jj];
    }
    if (okHi && el_lt((double)nHi, legs)) {
        nHi = nHi + 1;
        if (nHi >= 2 && el_ge(hiPrev, high[jj])) hiOk = false;
        hiPrev = high[jj];
        if (nHi == 1) hiPx1 = high[jj];
        if (nHi == 2) hiPx2 = high[jj];
    }
}
flatHi = (nHi >= 2) && el_le(std::fabs(hiPx1 - hiPx2), levelTolAtr * atrValue);
flatLo = (nLo >= 2) && el_le(std::fabs(loPx1 - loPx2), levelTolAtr * atrValue);
haveAsc = el_ge(legs, 2.0) && el_ge((double)nLo, legs) && loOk && flatHi;
haveDesc = el_ge(legs, 2.0) && el_ge((double)nHi, legs) && hiOk && flatLo;
